CREATE TABLE source(id text PRIMARY KEY,name text NOT NULL,mode text NOT NULL,coverage text NOT NULL DEFAULT 'unknown',last_success timestamptz,checkpoint text,access_notes text NOT NULL);
INSERT INTO source VALUES ('gem','GeM public bids','restricted','unknown',NULL,NULL,'Public pages reachable; authorized bulk data access/reproduction not verified. Direct collection disabled.'),('import','Authorized imports','import','partial',NULL,NULL,'Operator supplied CSV/JSON; national denominator unknown.');
CREATE TABLE collection_run(id uuid PRIMARY KEY,source_id text REFERENCES source(id),started_at timestamptz NOT NULL DEFAULT now(),finished_at timestamptz,status text NOT NULL,discovered integer NOT NULL DEFAULT 0,inserted integer NOT NULL DEFAULT 0,updated integer NOT NULL DEFAULT 0,unchanged integer NOT NULL DEFAULT 0,rejected integer NOT NULL DEFAULT 0,error text,provenance text NOT NULL);
CREATE TABLE organization(id uuid PRIMARY KEY,source_key text UNIQUE NOT NULL,name text NOT NULL,state text,district text,department text,ministry text,type text);
CREATE TABLE category(id text PRIMARY KEY,parent_id text REFERENCES category(id),name text NOT NULL,active boolean NOT NULL DEFAULT false);
CREATE TABLE product(id text PRIMARY KEY,name text NOT NULL,category_id text NOT NULL REFERENCES category(id),aliases jsonb NOT NULL DEFAULT '[]');
CREATE TABLE tender(id uuid PRIMARY KEY,bid_number text UNIQUE NOT NULL,title text NOT NULL,source_url text NOT NULL,source_id text REFERENCES source(id),organization_id uuid NOT NULL REFERENCES organization(id),published_at date,closes_at timestamptz,status text NOT NULL,estimated_value numeric(20,2),emd numeric(20,2),description text NOT NULL DEFAULT '',related_bid_number text,revision_at timestamptz,first_seen timestamptz NOT NULL DEFAULT now(),last_checked timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),current_hash text NOT NULL,raw jsonb NOT NULL, CHECK(estimated_value>=0),CHECK(emd>=0));
CREATE TABLE tender_version(id uuid PRIMARY KEY,tender_id uuid NOT NULL REFERENCES tender(id),hash text NOT NULL,observed_at timestamptz NOT NULL DEFAULT now(),run_id uuid REFERENCES collection_run(id),raw jsonb NOT NULL);
CREATE TABLE document(id uuid PRIMARY KEY,tender_id uuid NOT NULL REFERENCES tender(id),url text NOT NULL,label text NOT NULL,sha256 text,UNIQUE(tender_id,url));
CREATE TABLE line_item(id uuid PRIMARY KEY,tender_id uuid NOT NULL REFERENCES tender(id),source_key text NOT NULL,original_name text NOT NULL,product_id text REFERENCES product(id),quantity numeric(18,4),unit text NOT NULL,estimated_value numeric(20,2),evidence text NOT NULL,confidence numeric(4,3) NOT NULL,classification_reason text NOT NULL,needs_review boolean NOT NULL,UNIQUE(tender_id,source_key),CHECK(quantity>=0),CHECK(estimated_value>=0));
CREATE TABLE destination(id uuid PRIMARY KEY,line_item_id uuid NOT NULL REFERENCES line_item(id) ON DELETE CASCADE,state text NOT NULL,district text,city text,confirmed boolean NOT NULL,quantity numeric(18,4),evidence text NOT NULL,CHECK(quantity>=0));
CREATE TABLE correction(id uuid PRIMARY KEY,tender_id uuid NOT NULL REFERENCES tender(id),source_key text NOT NULL,product_id text REFERENCES product(id),reason text NOT NULL,actor text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE job(id uuid PRIMARY KEY,kind text NOT NULL,payload jsonb NOT NULL,status text NOT NULL DEFAULT 'pending',attempts int NOT NULL DEFAULT 0,available_at timestamptz NOT NULL DEFAULT now(),locked_at timestamptz,finished_at timestamptz,last_error text,created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX one_feed_job ON job(kind) WHERE kind='feed' AND status IN ('pending','running');
CREATE TABLE analytics_snapshot(id uuid PRIMARY KEY,created_at timestamptz NOT NULL DEFAULT now(),metrics jsonb NOT NULL);
CREATE INDEX tender_publication_idx ON tender(published_at);
CREATE INDEX tender_org_idx ON tender(organization_id);
CREATE INDEX line_product_idx ON line_item(product_id,tender_id);
CREATE INDEX destination_state_idx ON destination(state,district,line_item_id) WHERE confirmed;
CREATE INDEX line_tender_idx ON line_item(tender_id);
CREATE INDEX job_queue_idx ON job(available_at) WHERE status='pending';
CREATE INDEX versions_tender_idx ON tender_version(tender_id,observed_at);
CREATE INDEX correction_current_idx ON correction(tender_id,source_key,created_at DESC);
